(450883, 41462, 12075, '<td valign="top">this is my 1st 10 for this challenge..it is so pleasing to the eye..the DOF is perfect..cropping is right on..fantastic job!</td>', 'this is my 1st 10 for this challenge..it is so pleasing to the eye..the DOF is perfect..cropping is right on..fantastic job!', '2003-10-15 04:33:49.000000', NULL, 1),
