(451578, 42145, 10625, '<td valign="top">great clarity, vivid colours, detailed, good choice of leaf. 8</td>', 'great clarity, vivid colours, detailed, good choice of leaf. 8', '2003-10-15 18:35:39.000000', NULL, 1),
