(451596, 42269, 7543, '<td valign="top">Good shot, maybe the dof should cover the eye? 7</td>', 'Good shot, maybe the dof should cover the eye? 7', '2003-10-15 19:39:16.000000', NULL, 1),
(451599, 42163, 13189, '<td valign="top">the composition is great, the expression of the operator good also, but the small details of the cropping of the lamp''s edge and the chair, and a little over saturation does damage to an otherwise excellent photo (to my humble opinion)</td>', 'the composition is great, the expression of the operator good also, but the small details of the cropping of the lamp''s edge and the chair, and a little over saturation does damage to an otherwise excellent photo (to my humble opinion)', '2003-10-15 19:46:01.000000', NULL, 1),
(451601, 42240, 8860, '<td valign="top">What a rare capture (at least for a Brit anyway). Despite some noise in your shot, this is eerily beautiful - I''ve always longed to see the Northern Lights. Your shot is probably losing votes due to the lack of challenge relevance but I like it for the scene that it shares. <br/> <br/>Well composed. A shorter exposure would deepen the sky colour and reduce glare.</td>', 'What a rare capture (at least for a Brit anyway). Despite some noise in your shot, this is eerily beautiful - I''ve always longed to see the Northern Lights. Your shot is probably losing votes due to the lack of challenge relevance but I like it for the scene that it shares.  Well composed. A shorter exposure would deepen the sky colour and reduce glare.', '2003-10-15 19:46:58.000000', NULL, 1),
(451604, 42331, 13189, '<td valign="top">excellent. maybe the right side of the sphere should be a little darker. just a bit... good work!</td>', 'excellent. maybe the right side of the sphere should be a little darker. just a bit... good work!', '2003-10-15 19:49:07.000000', NULL, 1),
(451608, 42227, 9949, '<td valign="top">My favourite, a 10!</td>', 'My favourite, a 10!', '2003-10-15 19:53:05.000000', NULL, 1),
(451610, 42128, 13189, '<td valign="top">too much blue around. I would strngthen the sephia away from the welder and work on smaller flares. otherwise good. nice composition. Henry would be proud.</td>', 'too much blue around. I would strngthen the sephia away from the welder and work on smaller flares. otherwise good. nice composition. Henry would be proud.', '2003-10-15 19:53:58.000000', NULL, 1),
(451611, 41711, 2223, '<td valign="top">Ain''t that the truth!</td>', 'Ain''t that the truth!', '2003-10-15 19:55:06.000000', NULL, 1),
