(452014, 42234, 6886, '<td valign="top">Nice colors, but should have incresed the Dof so that the rim of the test tubes does not mix with the white background. Over all Very good job!</td>', 'Nice colors, but should have incresed the Dof so that the rim of the test tubes does not mix with the white background. Over all Very good job!', '2003-10-16 01:39:45.000000', NULL, 1),
(452017, 41831, 6886, '<td valign="top">Wow, this is a really great shot, but unfortunately i dont see the link here with science. Anyway i like the composition and the lighting in this shot! Keep it up.</td>', 'Wow, this is a really great shot, but unfortunately i dont see the link here with science. Anyway i like the composition and the lighting in this shot! Keep it up.', '2003-10-16 01:41:57.000000', NULL, 1),
(452020, 42187, 9441, '<td valign="top">I love the way you captured the droplets...very intricate detail, nicely done.</td>', 'I love the way you captured the droplets...very intricate detail, nicely done.', '2003-10-16 01:42:50.000000', NULL, 1),
(452061, 42124, 12361, '<td valign="top">good idea, nicely executed</td>', 'good idea, nicely executed', '2003-10-16 02:37:02.000000', NULL, 1),
(452062, 42187, 12361, '<td valign="top">great shot!</td>', 'great shot!', '2003-10-16 02:41:07.000000', NULL, 1),
