(452156, 42202, 10739, '<td valign="top">I would prefer to focus the dies in the middle</td>', 'I would prefer to focus the dies in the middle', '2003-10-16 06:32:11.000000', NULL, 1),
(452157, 41812, 10739, '<td valign="top">The color is nice, but I think that''s not enough to support the pic</td>', 'The color is nice, but I think that''s not enough to support the pic', '2003-10-16 06:33:01.000000', NULL, 1),
