(452170, 42321, 12733, '<td valign="top">Wow, it feels like you could go there tomorrow. Nice, tight crop makes it stand out well. What kind of equipment do you need for photos like this?</td>', 'Wow, it feels like you could go there tomorrow. Nice, tight crop makes it stand out well. What kind of equipment do you need for photos like this?', '2003-10-16 06:50:32.000000', NULL, 1),
(452171, 42204, 10739, '<td valign="top">does not fit well on the challenge ... don''t you think ?</td>', 'does not fit well on the challenge ... don''t you think ?', '2003-10-16 06:50:33.000000', NULL, 1),
