(452174, 42326, 12733, '<td valign="top">I like the bands of color and the ambiguity of the picture.</td>', 'I like the bands of color and the ambiguity of the picture.', '2003-10-16 06:52:37.000000', NULL, 1),
(452175, 42342, 10739, '<td valign="top">Bad composition, not very good light, the girl moving ... a lot of room for improvement</td>', 'Bad composition, not very good light, the girl moving ... a lot of room for improvement', '2003-10-16 06:52:55.000000', NULL, 1),
(452176, 42064, 12733, '<td valign="top">Interesting solution to the challenge and brilliant colors. Nice shot.</td>', 'Interesting solution to the challenge and brilliant colors. Nice shot.', '2003-10-16 06:56:56.000000', NULL, 1),
(452177, 42182, 12733, '<td valign="top">The lighting and color are spectacular. Did you use a filter or adjustments to the white balance or some other technique?</td>', 'The lighting and color are spectacular. Did you use a filter or adjustments to the white balance or some other technique?', '2003-10-16 07:01:10.000000', NULL, 1),
(452180, 42140, 12733, '<td valign="top">A clever concept, brilliantly photographed. I love the pure primary colors.</td>', 'A clever concept, brilliantly photographed. I love the pure primary colors.', '2003-10-16 07:03:54.000000', NULL, 1),
(452182, 42096, 12733, '<td valign="top">This is one of the more beautiful fall colors shots. But, for the record, once the green is gone, the photosynthesis stops.</td>', 'This is one of the more beautiful fall colors shots. But, for the record, once the green is gone, the photosynthesis stops.', '2003-10-16 07:05:09.000000', NULL, 1),
(452184, 42308, 12733, '<td valign="top">Nice still-life arrangement. Watch out for "revenuers."</td>', 'Nice still-life arrangement. Watch out for "revenuers."', '2003-10-16 07:07:00.000000', NULL, 1),
(452185, 41792, 12733, '<td valign="top">A nice touch of mystery. What are they? Also, the colors are brilliant and the shapes keep you looking.</td>', 'A nice touch of mystery. What are they? Also, the colors are brilliant and the shapes keep you looking.', '2003-10-16 07:09:18.000000', NULL, 1),
(452186, 42236, 12733, '<td valign="top">The colors are brilliant, and I really like the leaf-covered water. The relationship to the challenge is tenuous at best, though.</td>', 'The colors are brilliant, and I really like the leaf-covered water. The relationship to the challenge is tenuous at best, though.', '2003-10-16 07:11:57.000000', NULL, 1),
(452188, 42273, 12733, '<td valign="top">An evil-looking crew, but very colorful. I have to restrain myself from writing a humorous caption - the expressions are great.</td>', 'An evil-looking crew, but very colorful. I have to restrain myself from writing a humorous caption - the expressions are great.', '2003-10-16 07:17:41.000000', NULL, 1),
(452189, 42128, 12733, '<td valign="top">Brilliant color, good lighting and nice composition.</td>', 'Brilliant color, good lighting and nice composition.', '2003-10-16 07:20:05.000000', NULL, 1),
(452190, 42143, 12733, '<td valign="top">Very nice blur control. How many exposures did it take to get that just right?</td>', 'Very nice blur control. How many exposures did it take to get that just right?', '2003-10-16 07:21:56.000000', NULL, 1),
(452191, 42145, 12733, '<td valign="top">At this level of closeup, the leaf looks like a river with irrigation channels. And, in a way, that''s what those veins are. Brilliant idea, beautifully executed.</td>', 'At this level of closeup, the leaf looks like a river with irrigation channels. And, in a way, that''s what those veins are. Brilliant idea, beautifully executed.', '2003-10-16 07:24:33.000000', NULL, 1),
(452192, 42287, 12733, '<td valign="top">Perfect lighting, nice framing and a good choice of background. Nice shot.</td>', 'Perfect lighting, nice framing and a good choice of background. Nice shot.', '2003-10-16 07:26:09.000000', NULL, 1),
(452193, 41759, 12733, '<td valign="top">Super closeups reveal so much - and this is a beautiful subject.</td>', 'Super closeups reveal so much - and this is a beautiful subject.', '2003-10-16 07:29:04.000000', NULL, 1),
