(453708, 42298, 5792, '<td valign="top">Nicely composed. Framing works even though the container is cropped off at the bottom (at least in my opinion, but others may disagree). Good clarity, lighting and contrast.</td>', 'Nicely composed. Framing works even though the container is cropped off at the bottom (at least in my opinion, but others may disagree). Good clarity, lighting and contrast.', '2003-10-17 10:55:32.000000', NULL, 1),
(453712, 42266, 5792, '<td valign="top">Exceptionally well composed image. The color difference between ypur primary subject and the background helps make this an outstanding entry. Good use of DOF.</td>', 'Exceptionally well composed image. The color difference between ypur primary subject and the background helps make this an outstanding entry. Good use of DOF.', '2003-10-17 10:57:12.000000', NULL, 1),
(453713, 42259, 5792, '<td valign="top">Nice capture. Good color. Superb lighting. Great image.</td>', 'Nice capture. Good color. Superb lighting. Great image.', '2003-10-17 10:58:28.000000', NULL, 1),
(453716, 42349, 5792, '<td valign="top">Nicely done all the way around. The choice of blue lighting is a great touch.</td>', 'Nicely done all the way around. The choice of blue lighting is a great touch.', '2003-10-17 11:01:16.000000', NULL, 1),
(453719, 41620, 5792, '<td valign="top">Well composed and framed image. Great angle.</td>', 'Well composed and framed image. Great angle.', '2003-10-17 11:02:28.000000', NULL, 1),
(453720, 42240, 2241, '<td valign="top">this is truly an outstanding photo.</td>', 'this is truly an outstanding photo.', '2003-10-17 11:02:34.000000', NULL, 1),
(453721, 42145, 5792, '<td valign="top">Beautifully composed image. Great color and clarity. This is a technically superior image.</td>', 'Beautifully composed image. Great color and clarity. This is a technically superior image.', '2003-10-17 11:03:30.000000', NULL, 1),
(453722, 42109, 5792, '<td valign="top">Excellant capture.</td>', 'Excellant capture.', '2003-10-17 11:03:59.000000', NULL, 1),
(453723, 42090, 2241, '<td valign="top">This fits the challenge of really showing the development of technology...as opposed to science...better than any other picture I''ve seen.  Wish I''d thought of doing something like this.</td>', 'This fits the challenge of really showing the development of technology...as opposed to science...better than any other picture I''ve seen.  Wish I''d thought of doing something like this.', '2003-10-17 11:04:10.000000', NULL, 1),
