(453769, 42159, 11184, '<td valign="top">Cool...what the heck is that thing?  Looks like a scene from Tron.</td>', 'Cool...what the heck is that thing?  Looks like a scene from Tron.', '2003-10-17 11:37:21.000000', NULL, 1),
(453771, 41965, 2241, '<td valign="top">very imaginative.  I seem to have lost my imagination and wish I''d thought it through as well as you did.</td>', 'very imaginative.  I seem to have lost my imagination and wish I''d thought it through as well as you did.', '2003-10-17 11:39:45.000000', NULL, 1),
(453774, 42197, 2241, '<td valign="top">very nice</td>', 'very nice', '2003-10-17 11:41:05.000000', NULL, 1),
(453777, 42331, 11184, '<td valign="top">Cool...i really like the subtle and ominous way you shot this one.  Looks like a mysterious planet in space or something.  Great shot.</td>', 'Cool...i really like the subtle and ominous way you shot this one.  Looks like a mysterious planet in space or something.  Great shot.', '2003-10-17 11:41:55.000000', NULL, 1),
(453783, 41863, 11184, '<td valign="top">Good shot!  I like how you showed Entomology ''at work'' instead of just showing a butterfly and having the person assume the science referenced.</td>', 'Good shot!  I like how you showed Entomology ''at work'' instead of just showing a butterfly and having the person assume the science referenced.', '2003-10-17 11:45:22.000000', NULL, 1),
(453787, 42163, 11184, '<td valign="top">Hey wow, nice.  Looks like a scene right out of a movie.  Good capture of the golden age of science.  You must either have put a lot of thought and time into this, or just happen to know this guy who is sitting there like that passionatley every night.     Oooor...ORRR....you have a time machine.  Hey, that would have been a cool shot.  Why didn\''t you just shoot that??</td>', 'Hey wow, nice.  Looks like a scene right out of a movie.  Good capture of the golden age of science.  You must either have put a lot of thought and time into this, or just happen to know this guy who is sitting there like that passionatley every night.     Oooor...ORRR....you have a time machine.  Hey, that would have been a cool shot.  Why didn\''t you just shoot that??', '2003-10-17 11:49:12.000000', NULL, 1),
(453823, 42349, 2241, '<td valign="top">great imagination.  wonderful technical skill</td>', 'great imagination.  wonderful technical skill', '2003-10-17 12:29:31.000000', NULL, 1),
(453824, 42225, 2241, '<td valign="top">beautiful</td>', 'beautiful', '2003-10-17 12:29:47.000000', NULL, 1),
(453848, 42125, 2241, '<td valign="top">very good geology interpretation</td>', 'very good geology interpretation', '2003-10-17 13:13:08.000000', NULL, 1),
