(453855, 41906, 11687, '<td valign="top">Close :)  First you get carbonic acid, which immediately decomposes to CO2 and water.  The nasty stuff you''re left with is sodium acetate.  And that''s your chemistry lesson for the day.  Nice pic!</td>', 'Close :)  First you get carbonic acid, which immediately decomposes to CO2 and water.  The nasty stuff you''re left with is sodium acetate.  And that''s your chemistry lesson for the day.  Nice pic!', '2003-10-17 13:22:55.000000', NULL, 1),
(453872, 42167, 5792, '<td valign="top">Beautiful! Great use of DOF and the ROT. Nice composition. You are to be commended for this outstanding image.</td>', 'Beautiful! Great use of DOF and the ROT. Nice composition. You are to be commended for this outstanding image.', '2003-10-17 13:58:43.000000', NULL, 1),
