(454584, 42313, 4210, '<td valign="top">Looks a tiny bit pixelated. Nice colour. Focus and lighting need a little work, but overall good.</td>', 'Looks a tiny bit pixelated. Nice colour. Focus and lighting need a little work, but overall good.', '2003-10-18 12:41:02.000000', NULL, 1),
(454585, 41811, 4210, '<td valign="top">Great colour and composition!</td>', 'Great colour and composition!', '2003-10-18 12:41:21.000000', NULL, 1),
